"""Generate src/cli/fingerprints.rs: a SHA-256 per service of the argument
tables the reference builds for every operation and waiter command
(`ServiceOperation.arg_table` after all `building-argument-table`
handlers), skipping the operations `commands::is_customized` reports as
not implemented and the ones listed in MODEL_GAPS.

    HOME=$(mktemp -d) PYTHONPATH=$AWSR_REFERENCE_SRC \
        python3 src/cli/testdata/gen_fingerprints.py > src/cli/fingerprints.rs
"""

import hashlib
import os
import re

import awscli  # noqa: F401

from awscli.clidriver import ServiceCommand, ServiceOperation, create_clidriver
from awscli.customizations.waiters import WaitCommand

HERE = os.path.dirname(os.path.abspath(__file__))

# Operations whose input shapes gain members from service-2.sdk-extras.json,
# which the embedded models do not merge yet.
MODEL_GAPS = [
    ('docdb', 'copy-db-cluster-snapshot'),
    ('docdb', 'create-db-cluster'),
    ('neptune', 'copy-db-cluster-snapshot'),
    ('neptune', 'create-db-cluster'),
    ('rds', 'copy-db-cluster-snapshot'),
    ('rds', 'copy-db-snapshot'),
    ('rds', 'create-db-cluster'),
    ('rds', 'create-db-instance-read-replica'),
    ('rds', 'start-db-instance-automated-backups-replication'),
]


def customized():
    with open(os.path.join(HERE, '..', 'commands.rs')) as f:
        text = f.read()
    block = text.split('static CUSTOMIZED_OPERATIONS')[1].split('];')[0]
    return set(re.findall(r'\("([^"]+)", "([^"]+)"\)', block))


def fingerprint(table):
    out = []
    for key, arg in table.items():
        cls = type(arg).__name__
        dest = arg._destination if cls == 'BooleanArgument' else ''
        undocumented = int(bool(getattr(arg, '_UNDOCUMENTED', False)))
        out.append(
            f'{key}|{cls}|{arg.cli_name}|{int(bool(arg.required))}|'
            f'{arg.py_name}|{dest}|{undocumented}\n'
        )
    return ''.join(out)


def main():
    skip = customized() | set(MODEL_GAPS)
    driver = create_clidriver()
    lines = [
        '//! Generated by `src/cli/testdata/gen_fingerprints.py`. Do not edit.',
        '',
        '/// Operations left out of the fingerprints (see `MODEL_GAPS` in the',
        '/// generator).',
        'pub(super) const MODEL_GAPS: &[(&str, &str)] = &[',
    ]
    lines += [f'    ("{s}", "{o}"),' for s, o in MODEL_GAPS]
    lines += [
        '];',
        '',
        '/// (CLI service, SHA-256 of the sorted per-command fingerprints).',
        'pub(super) const FINGERPRINTS: &[(&str, &str)] = &[',
    ]
    for name, cmd in driver._get_command_table().items():
        if type(cmd) is not ServiceCommand:
            continue
        cmd = create_clidriver()._get_command_table()[name]
        blocks = []
        for key, sub in cmd.subcommand_table.items():
            if type(sub) is ServiceOperation and (name, key) not in skip:
                blocks.append(f'## {name} {key}\n' + fingerprint(sub.arg_table))
            elif isinstance(sub, WaitCommand) and key == 'wait':
                for wkey, wsub in sub.subcommand_table.items():
                    blocks.append(
                        f'## {name} wait {wkey}\n' + fingerprint(wsub.arg_table)
                    )
        blocks.sort()
        digest = hashlib.sha256(''.join(blocks).encode()).hexdigest()
        lines.append(f'    ("{name}", "{digest}"),')
    lines.append('];')
    print('\n'.join(lines))


if __name__ == '__main__':
    main()
